-- MAGIC 2. Attach to a SQL warehouse (or DBR 13.3+) and *Run all*.
-- MAGIC 3. Cells: config -> 01 staging (`read_files`) -> 02 cleaning -> 03 star schema -> 04 KPIs -> 05 data quality -> visual queries.

-- COMMAND ----------

-- Config
CREATE SCHEMA IF NOT EXISTS workspace.da_learn_06;
CREATE VOLUME IF NOT EXISTS workspace.da_learn_06.raw;
USE CATALOG workspace;
USE SCHEMA da_learn_06;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 01 Staging (raw landing, no type inference for CSV; casting happens in 02)

-- COMMAND ----------

CREATE OR REPLACE TABLE stg_flights AS
SELECT * FROM read_files('/Volumes/workspace/da_learn_06/raw/flights.parquet', format => 'parquet');

-- COMMAND ----------

CREATE OR REPLACE TABLE stg_airlines AS
SELECT * FROM read_files('/Volumes/workspace/da_learn_06/raw/airlines.parquet', format => 'parquet');

-- COMMAND ----------

CREATE OR REPLACE TABLE stg_airports AS
SELECT * FROM read_files('/Volumes/workspace/da_learn_06/raw/airports.parquet', format => 'parquet');

-- COMMAND ----------

CREATE OR REPLACE TABLE stg_cancellation_codes AS
SELECT * FROM read_files('/Volumes/workspace/da_learn_06/raw/cancellation_codes.parquet', format => 'parquet');

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 02 Cleaning (`sql/02_cleaning.sql`)

-- COMMAND ----------

-- 02_cleaning.sql  types, trimming, standardisation, dates, dedupe, outlier and integrity flags.

CREATE OR REPLACE TABLE cln_airlines AS
SELECT UPPER(TRIM(CAST(IATA_CODE AS STRING))) AS airline_code, TRIM(CAST(AIRLINE AS STRING)) AS airline_name
FROM stg_airlines
WHERE IATA_CODE IS NOT NULL
QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(CAST(IATA_CODE AS STRING))) ORDER BY TRIM(CAST(AIRLINE AS STRING))) = 1;

-- COMMAND ----------

-- Airports: trim, typed coordinates, flag the 3 airports that ship without lat/long

CREATE OR REPLACE TABLE cln_airports AS
SELECT UPPER(TRIM(CAST(IATA_CODE AS STRING))) AS iata_code, TRIM(CAST(AIRPORT AS STRING)) AS airport_name,
  TRIM(CAST(CITY AS STRING)) AS city, UPPER(TRIM(CAST(STATE AS STRING))) AS state, TRIM(CAST(COUNTRY AS STRING)) AS country,
  TRY_CAST(LATITUDE AS DOUBLE) AS latitude, TRY_CAST(LONGITUDE AS DOUBLE) AS longitude,
  CASE WHEN TRY_CAST(LATITUDE AS DOUBLE) IS NULL OR TRY_CAST(LONGITUDE AS DOUBLE) IS NULL THEN 1 ELSE 0 END AS dq_missing_coords
FROM stg_airports
WHERE IATA_CODE IS NOT NULL
QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(CAST(IATA_CODE AS STRING))) ORDER BY TRIM(CAST(AIRPORT AS STRING))) = 1;

-- COMMAND ----------

CREATE OR REPLACE TABLE cln_cancellation_codes AS
SELECT UPPER(TRIM(CAST(CANCELLATION_REASON AS STRING))) AS cancellation_code, TRIM(CAST(CANCELLATION_DESCRIPTION AS STRING)) AS cancellation_reason
FROM stg_cancellation_codes WHERE CANCELLATION_REASON IS NOT NULL;

-- COMMAND ----------

-- Flights: typed + derived columns and one 0/1 flag per data-quality rule

CREATE OR REPLACE TABLE cln_flights_flagged AS
WITH t AS (
  SELECT
    TRY_CAST(YEAR AS INT) AS yr, TRY_CAST(MONTH AS INT) AS mo, TRY_CAST(DAY AS INT) AS dy, TRY_CAST(DAY_OF_WEEK AS INT) AS bts_dow,
    UPPER(TRIM(CAST(AIRLINE AS STRING))) AS airline_code, TRY_CAST(FLIGHT_NUMBER AS INT) AS flight_number,
    NULLIF(UPPER(TRIM(CAST(TAIL_NUMBER AS STRING))), '') AS tail_number,
    UPPER(TRIM(CAST(ORIGIN_AIRPORT AS STRING))) AS origin_raw, UPPER(TRIM(CAST(DESTINATION_AIRPORT AS STRING))) AS dest_raw,
    TRY_CAST(SCHEDULED_DEPARTURE AS INT) AS sched_dep_hhmm, TRY_CAST(DEPARTURE_TIME AS INT) AS dep_hhmm,
    TRY_CAST(SCHEDULED_ARRIVAL AS INT) AS sched_arr_hhmm, TRY_CAST(ARRIVAL_TIME AS INT) AS arr_hhmm,
    TRY_CAST(DEPARTURE_DELAY AS INT) AS dep_delay_min, TRY_CAST(ARRIVAL_DELAY AS INT) AS arr_delay_min,
    TRY_CAST(TAXI_OUT AS INT) AS taxi_out_min, TRY_CAST(TAXI_IN AS INT) AS taxi_in_min,
    TRY_CAST(SCHEDULED_TIME AS INT) AS scheduled_time_min, TRY_CAST(ELAPSED_TIME AS INT) AS elapsed_time_min,
    TRY_CAST(AIR_TIME AS INT) AS air_time_min, TRY_CAST(DISTANCE AS INT) AS distance_mi,
    COALESCE(TRY_CAST(DIVERTED AS INT), 0) AS is_diverted, COALESCE(TRY_CAST(CANCELLED AS INT), 0) AS is_cancelled,
    NULLIF(UPPER(TRIM(CAST(CANCELLATION_REASON AS STRING))), '') AS cancellation_code,
    TRY_CAST(AIR_SYSTEM_DELAY AS INT) AS nas_delay_min, TRY_CAST(SECURITY_DELAY AS INT) AS security_delay_min,
    TRY_CAST(AIRLINE_DELAY AS INT) AS carrier_delay_min, TRY_CAST(LATE_AIRCRAFT_DELAY AS INT) AS late_aircraft_delay_min,
    TRY_CAST(WEATHER_DELAY AS INT) AS weather_delay_min
  FROM stg_flights
), d AS (
  SELECT t.*, make_date(yr, mo, dy) AS flight_date, yr * 10000 + mo * 100 + dy AS date_key,
    CAST(FLOOR(sched_dep_hhmm / 100) AS INT) % 24 AS sched_dep_hour,
    CASE WHEN TRY_CAST(origin_raw AS INT) IS NULL THEN origin_raw END AS origin_iata,
    CASE WHEN TRY_CAST(dest_raw AS INT) IS NULL THEN dest_raw END AS dest_iata,
    ROW_NUMBER() OVER (PARTITION BY yr, mo, dy, airline_code, flight_number, origin_raw, dest_raw, sched_dep_hhmm ORDER BY tail_number, dep_hhmm, arr_hhmm, sched_arr_hhmm, distance_mi) AS dup_rank
  FROM t
)
SELECT d.*,
  CASE WHEN is_cancelled = 1 THEN 'Cancelled' WHEN is_diverted = 1 THEN 'Diverted' ELSE 'Completed' END AS flight_status,
  CASE WHEN is_cancelled = 0 AND is_diverted = 0 AND arr_delay_min >= 15 THEN 1 ELSE 0 END AS is_arr_delayed_15,
  CASE WHEN is_cancelled = 0 AND is_diverted = 0 AND arr_delay_min < 15 THEN 1 ELSE 0 END AS is_on_time,
  CASE WHEN dup_rank > 1 THEN 1 ELSE 0 END AS dq_duplicate,
  CASE WHEN flight_date IS NULL OR yr <> 2015 THEN 1 ELSE 0 END AS dq_bad_date,
  CASE WHEN airline_code NOT IN (SELECT airline_code FROM cln_airlines) THEN 1 ELSE 0 END AS dq_unknown_airline,
  CASE WHEN origin_iata IS NULL OR dest_iata IS NULL THEN 1 ELSE 0 END AS dq_numeric_airport_code,
  CASE WHEN (origin_iata IS NOT NULL AND origin_iata NOT IN (SELECT iata_code FROM cln_airports))
         OR (dest_iata IS NOT NULL AND dest_iata NOT IN (SELECT iata_code FROM cln_airports)) THEN 1 ELSE 0 END AS dq_unknown_airport,
  CASE WHEN distance_mi IS NULL OR distance_mi <= 0 THEN 1 ELSE 0 END AS dq_bad_distance,
  CASE WHEN is_cancelled = 0 AND is_diverted = 0 AND arr_delay_min IS NULL THEN 1 ELSE 0 END AS dq_missing_arr_delay,
  CASE WHEN is_cancelled = 1 AND cancellation_code IS NULL THEN 1 ELSE 0 END AS dq_cancel_no_reason,
  CASE WHEN ABS(COALESCE(arr_delay_min, 0)) > 600 OR ABS(COALESCE(dep_delay_min, 0)) > 600 THEN 1 ELSE 0 END AS dq_delay_outlier,
  CASE WHEN nas_delay_min IS NOT NULL
        AND nas_delay_min + security_delay_min + carrier_delay_min + late_aircraft_delay_min + weather_delay_min <> arr_delay_min THEN 1 ELSE 0 END AS dq_cause_mismatch,
  CASE WHEN bts_dow <> ((dayofweek(make_date(yr, mo, dy)) + 5) % 7) + 1 THEN 1 ELSE 0 END AS dq_dow_mismatch
FROM d;

-- COMMAND ----------

-- Clean flights: drop duplicate flight keys (date, carrier, flight no, origin, destination, sched dep), bad dates and unknown carriers. Outliers and the

CREATE OR REPLACE TABLE cln_flights AS
SELECT * FROM cln_flights_flagged
WHERE dq_duplicate = 0 AND dq_bad_date = 0 AND dq_unknown_airline = 0;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 03 Star schema (`sql/03_model.sql`)

-- COMMAND ----------

-- 03_model.sql  star schema: fact_flights + dim_date, dim_airline, dim_airport, dim_cancellation

CREATE OR REPLACE TABLE dim_airline AS
SELECT airline_code, airline_name FROM cln_airlines;

-- COMMAND ----------

-- 'UNK' member catches the October 2015 rows whose airports arrive as numeric BTS ids

CREATE OR REPLACE TABLE dim_airport AS
SELECT iata_code AS airport_code, airport_name, city, state, country, latitude, longitude FROM cln_airports
UNION ALL
SELECT 'UNK', 'Unknown (Oct 2015 numeric BTS airport id)', NULL, NULL, NULL, NULL, NULL;

-- COMMAND ----------

CREATE OR REPLACE TABLE dim_cancellation AS
SELECT cancellation_code, cancellation_reason FROM cln_cancellation_codes
UNION ALL SELECT 'N', 'Not cancelled';

-- COMMAND ----------

CREATE OR REPLACE TABLE dim_date AS
SELECT DISTINCT date_key, flight_date, yr AS year, mo AS month,
  CASE mo WHEN 1 THEN '01 Jan' WHEN 2 THEN '02 Feb' WHEN 3 THEN '03 Mar' WHEN 4 THEN '04 Apr' WHEN 5 THEN '05 May' WHEN 6 THEN '06 Jun'
          WHEN 7 THEN '07 Jul' WHEN 8 THEN '08 Aug' WHEN 9 THEN '09 Sep' WHEN 10 THEN '10 Oct' WHEN 11 THEN '11 Nov' ELSE '12 Dec' END AS month_label,
  CAST(FLOOR((mo - 1) / 3) AS INT) + 1 AS quarter, dy AS day_of_month,
  bts_dow AS day_of_week,
  CASE bts_dow WHEN 1 THEN 'Mon' WHEN 2 THEN 'Tue' WHEN 3 THEN 'Wed' WHEN 4 THEN 'Thu' WHEN 5 THEN 'Fri' WHEN 6 THEN 'Sat' ELSE 'Sun' END AS day_name,
  CASE WHEN bts_dow IN (6, 7) THEN 1 ELSE 0 END AS is_weekend
FROM cln_flights;

-- COMMAND ----------

CREATE OR REPLACE TABLE fact_flights AS
SELECT date_key, airline_code, flight_number, tail_number,
  COALESCE(origin_iata, 'UNK') AS origin_code, COALESCE(dest_iata, 'UNK') AS dest_code,
  sched_dep_hhmm, sched_dep_hour, distance_mi,
  CASE WHEN distance_mi < 500 THEN '1 <500 mi' WHEN distance_mi < 1000 THEN '2 500-999 mi' WHEN distance_mi < 1500 THEN '3 1000-1499 mi'
       WHEN distance_mi < 2500 THEN '4 1500-2499 mi' ELSE '5 2500+ mi' END AS distance_band,
  flight_status, is_cancelled, is_diverted, COALESCE(cancellation_code, 'N') AS cancellation_code,
  is_on_time, is_arr_delayed_15, dep_delay_min, arr_delay_min, taxi_out_min, taxi_in_min, air_time_min, elapsed_time_min, scheduled_time_min,
  nas_delay_min, security_delay_min, carrier_delay_min, late_aircraft_delay_min, weather_delay_min,
  dq_delay_outlier, dq_numeric_airport_code
FROM cln_flights;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 04 Business KPIs (`sql/04_analysis.sql`)

-- COMMAND ----------

-- 04_analysis.sql  KPIs and business questions. On-time = arrived < 15 min late (BTS definition), measured

CREATE OR REPLACE TABLE a_kpi_headline AS
SELECT COUNT(*) AS flights,
  SUM(1 - is_cancelled - is_diverted) AS completed_flights,
  ROUND(COUNT(*) / COUNT(DISTINCT date_key), 0) AS avg_flights_per_day,
  ROUND(100.0 * SUM(is_on_time) / NULLIF(SUM(is_on_time + is_arr_delayed_15), 0), 2) AS on_time_pct,
  ROUND(100.0 * AVG(CAST(is_cancelled AS DOUBLE)), 2) AS cancelled_pct,
  ROUND(100.0 * AVG(CAST(is_diverted AS DOUBLE)), 2) AS diverted_pct,
  ROUND(AVG(CASE WHEN is_cancelled = 0 AND is_diverted = 0 THEN arr_delay_min END), 2) AS avg_arr_delay_min,
  ROUND(AVG(CASE WHEN is_cancelled = 0 THEN dep_delay_min END), 2) AS avg_dep_delay_min,
  ROUND(AVG(CASE WHEN is_arr_delayed_15 = 1 THEN arr_delay_min END), 2) AS avg_delay_when_late_min,
  SUM(CASE WHEN is_arr_delayed_15 = 1 THEN arr_delay_min ELSE 0 END) AS total_late_arrival_min,
  COUNT(DISTINCT airline_code) AS airlines,
  COUNT(DISTINCT CASE WHEN origin_code <> 'UNK' THEN origin_code END) AS origin_airports,
  ROUND(AVG(CAST(taxi_out_min AS DOUBLE)), 2) AS avg_taxi_out_min
FROM fact_flights;

-- COMMAND ----------

-- Q1: seasonality

CREATE OR REPLACE TABLE a_monthly AS
SELECT d.month, d.month_label, COUNT(*) AS flights,
  ROUND(100.0 * SUM(f.is_on_time) / NULLIF(SUM(f.is_on_time + f.is_arr_delayed_15), 0), 2) AS on_time_pct,
  ROUND(100.0 * AVG(CAST(f.is_cancelled AS DOUBLE)), 2) AS cancelled_pct,
  ROUND(AVG(CASE WHEN f.is_cancelled = 0 AND f.is_diverted = 0 THEN f.arr_delay_min END), 2) AS avg_arr_delay_min
FROM fact_flights f JOIN dim_date d ON d.date_key = f.date_key
GROUP BY d.month, d.month_label;

-- COMMAND ----------

CREATE OR REPLACE TABLE a_daily AS
SELECT d.flight_date, d.day_name, COUNT(*) AS flights, SUM(f.is_cancelled) AS cancelled,
  ROUND(100.0 * AVG(CAST(f.is_cancelled AS DOUBLE)), 2) AS cancelled_pct,
  ROUND(100.0 * SUM(f.is_on_time) / NULLIF(SUM(f.is_on_time + f.is_arr_delayed_15), 0), 2) AS on_time_pct
FROM fact_flights f JOIN dim_date d ON d.date_key = f.date_key
GROUP BY d.flight_date, d.day_name;

-- COMMAND ----------

CREATE OR REPLACE TABLE a_day_of_week AS
SELECT d.day_of_week, d.day_name, COUNT(*) AS flights, COUNT(DISTINCT d.date_key) AS days,
  ROUND(COUNT(*) / COUNT(DISTINCT d.date_key), 0) AS avg_flights_per_day,
  ROUND(100.0 * SUM(f.is_on_time) / NULLIF(SUM(f.is_on_time + f.is_arr_delayed_15), 0), 2) AS on_time_pct
FROM fact_flights f JOIN dim_date d ON d.date_key = f.date_key
GROUP BY d.day_of_week, d.day_name;

-- COMMAND ----------

-- Q2: which carriers are most / least reliable

CREATE OR REPLACE TABLE a_airline AS
SELECT a.airline_code, a.airline_name, COUNT(*) AS flights,
  ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS share_pct,
  ROUND(100.0 * SUM(f.is_on_time) / NULLIF(SUM(f.is_on_time + f.is_arr_delayed_15), 0), 2) AS on_time_pct,
  ROUND(100.0 * AVG(CAST(f.is_cancelled AS DOUBLE)), 2) AS cancelled_pct,
  ROUND(AVG(CASE WHEN f.is_cancelled = 0 AND f.is_diverted = 0 THEN f.arr_delay_min END), 2) AS avg_arr_delay_min,
  ROUND(AVG(CASE WHEN f.is_arr_delayed_15 = 1 THEN f.arr_delay_min END), 2) AS avg_delay_when_late_min
FROM fact_flights f JOIN dim_airline a ON a.airline_code = f.airline_code
GROUP BY a.airline_code, a.airline_name;

-- COMMAND ----------

-- Q3: what causes the delay minutes (BTS cause attribution, flights >= 15 min late)

CREATE OR REPLACE TABLE a_delay_causes AS
WITH s AS (
  SELECT 'Late-arriving aircraft' AS cause, SUM(late_aircraft_delay_min) AS minutes FROM fact_flights
  UNION ALL SELECT 'Airline / carrier', SUM(carrier_delay_min) FROM fact_flights
  UNION ALL SELECT 'National Air System', SUM(nas_delay_min) FROM fact_flights
  UNION ALL SELECT 'Weather', SUM(weather_delay_min) FROM fact_flights
  UNION ALL SELECT 'Security', SUM(security_delay_min) FROM fact_flights
)
SELECT cause, minutes, ROUND(100.0 * minutes / NULLIF(SUM(minutes) OVER (), 0), 2) AS share_pct FROM s;

-- COMMAND ----------

CREATE OR REPLACE TABLE a_cancellation_reasons AS
SELECT c.cancellation_reason, COUNT(*) AS cancelled_flights,
  ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS share_pct
FROM fact_flights f JOIN dim_cancellation c ON c.cancellation_code = f.cancellation_code
WHERE f.is_cancelled = 1
GROUP BY c.cancellation_reason;

-- COMMAND ----------

-- Q4: time of day - delays build up through the day

CREATE OR REPLACE TABLE a_hourly AS
SELECT sched_dep_hour, COUNT(*) AS flights,
  ROUND(AVG(CASE WHEN is_cancelled = 0 THEN dep_delay_min END), 2) AS avg_dep_delay_min,
  ROUND(100.0 * SUM(is_on_time) / NULLIF(SUM(is_on_time + is_arr_delayed_15), 0), 2) AS on_time_pct
FROM fact_flights
GROUP BY sched_dep_hour;

-- COMMAND ----------

-- Q5: airports (Oct 2015 rows without IATA codes excluded) - the 15 busiest origins

CREATE OR REPLACE TABLE a_origin_airports AS
SELECT f.origin_code, p.airport_name, p.city, p.state, COUNT(*) AS departures,
  ROUND(100.0 * SUM(f.is_on_time) / NULLIF(SUM(f.is_on_time + f.is_arr_delayed_15), 0), 2) AS on_time_pct,
  ROUND(AVG(CASE WHEN f.is_cancelled = 0 THEN f.dep_delay_min END), 2) AS avg_dep_delay_min,
  ROUND(100.0 * AVG(CAST(f.is_cancelled AS DOUBLE)), 2) AS cancelled_pct,
  ROUND(AVG(CAST(f.taxi_out_min AS DOUBLE)), 2) AS avg_taxi_out_min
FROM fact_flights f JOIN dim_airport p ON p.airport_code = f.origin_code
WHERE f.origin_code <> 'UNK'
GROUP BY f.origin_code, p.airport_name, p.city, p.state;

-- COMMAND ----------

CREATE OR REPLACE TABLE a_routes AS
SELECT origin_code || '-' || dest_code AS route, COUNT(*) AS flights, ROUND(AVG(CAST(distance_mi AS DOUBLE)), 0) AS distance_mi,
  ROUND(100.0 * SUM(is_on_time) / NULLIF(SUM(is_on_time + is_arr_delayed_15), 0), 2) AS on_time_pct
FROM fact_flights
WHERE origin_code <> 'UNK' AND dest_code <> 'UNK'
GROUP BY origin_code, dest_code;

-- COMMAND ----------

CREATE OR REPLACE TABLE a_distance_bands AS
SELECT distance_band, COUNT(*) AS flights,
  ROUND(100.0 * SUM(is_on_time) / NULLIF(SUM(is_on_time + is_arr_delayed_15), 0), 2) AS on_time_pct,
  ROUND(100.0 * AVG(CAST(is_cancelled AS DOUBLE)), 2) AS cancelled_pct,
  ROUND(AVG(CASE WHEN is_cancelled = 0 AND is_diverted = 0 THEN arr_delay_min END), 2) AS avg_arr_delay_min,
  ROUND(AVG(CASE WHEN is_cancelled = 0 AND is_diverted = 0 THEN dep_delay_min - arr_delay_min END), 2) AS avg_time_made_up_min
FROM fact_flights
GROUP BY distance_band;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 05 Data-quality checks (`sql/05_quality_checks.sql`)

-- COMMAND ----------

-- 05_quality_checks.sql  before/after counts, DQ issue counts and hard assertions

CREATE OR REPLACE TABLE dq_row_counts AS
SELECT 'flights' AS entity, (SELECT COUNT(*) FROM stg_flights) AS raw_rows, (SELECT COUNT(*) FROM cln_flights) AS clean_rows,
       (SELECT COUNT(*) FROM stg_flights) - (SELECT COUNT(*) FROM cln_flights) AS removed_rows, 'flight leg' AS grain
UNION ALL SELECT 'airlines', (SELECT COUNT(*) FROM stg_airlines), (SELECT COUNT(*) FROM cln_airlines), (SELECT COUNT(*) FROM stg_airlines) - (SELECT COUNT(*) FROM cln_airlines), 'carrier'
UNION ALL SELECT 'airports', (SELECT COUNT(*) FROM stg_airports), (SELECT COUNT(*) FROM cln_airports), (SELECT COUNT(*) FROM stg_airports) - (SELECT COUNT(*) FROM cln_airports), 'airport'
UNION ALL SELECT 'fact_flights', NULL, (SELECT COUNT(*) FROM fact_flights), NULL, 'flight leg'
UNION ALL SELECT 'dim_date', NULL, (SELECT COUNT(*) FROM dim_date), NULL, 'day'
UNION ALL SELECT 'dim_airline', NULL, (SELECT COUNT(*) FROM dim_airline), NULL, 'carrier'
UNION ALL SELECT 'dim_airport', NULL, (SELECT COUNT(*) FROM dim_airport), NULL, 'airport (+UNK)'
UNION ALL SELECT 'dim_cancellation', NULL, (SELECT COUNT(*) FROM dim_cancellation), NULL, 'cancellation code (+N)';

-- COMMAND ----------

-- flags overlap, so each count is "rows with this flag"

CREATE OR REPLACE TABLE dq_issues AS
SELECT 'duplicate flight key (date, carrier, flight no, origin, dest, sched dep) - removed' AS check_name, (SELECT SUM(dq_duplicate) FROM cln_flights_flagged) AS affected_rows
UNION ALL SELECT 'invalid / non-2015 date - removed', (SELECT SUM(dq_bad_date) FROM cln_flights_flagged)
UNION ALL SELECT 'carrier not in airlines lookup - removed', (SELECT SUM(dq_unknown_airline) FROM cln_flights_flagged)
UNION ALL SELECT 'numeric BTS airport id instead of IATA (Oct 2015) - kept as UNK', (SELECT SUM(dq_numeric_airport_code) FROM cln_flights_flagged)
UNION ALL SELECT 'IATA airport not in airports lookup', (SELECT SUM(dq_unknown_airport) FROM cln_flights_flagged)
UNION ALL SELECT 'distance missing or <= 0', (SELECT SUM(dq_bad_distance) FROM cln_flights_flagged)
UNION ALL SELECT 'completed flight without arrival delay', (SELECT SUM(dq_missing_arr_delay) FROM cln_flights_flagged)
UNION ALL SELECT 'cancelled without reason code', (SELECT SUM(dq_cancel_no_reason) FROM cln_flights_flagged)
UNION ALL SELECT 'delay > 10 h (outlier, kept and flagged)', (SELECT SUM(dq_delay_outlier) FROM cln_flights_flagged)
UNION ALL SELECT 'cause minutes do not sum to arrival delay', (SELECT SUM(dq_cause_mismatch) FROM cln_flights_flagged)
UNION ALL SELECT 'BTS day_of_week disagrees with date', (SELECT SUM(dq_dow_mismatch) FROM cln_flights_flagged)
UNION ALL SELECT 'same flight no + origin + sched dep, different destination (multi-leg; kept)', (SELECT COUNT(*) FROM (SELECT yr, mo, dy, airline_code, flight_number, origin_raw, sched_dep_hhmm FROM cln_flights_flagged
      GROUP BY yr, mo, dy, airline_code, flight_number, origin_raw, sched_dep_hhmm HAVING COUNT(*) > 1) x)
UNION ALL SELECT 'tail number missing (kept)', (SELECT COUNT(*) FROM cln_flights_flagged WHERE tail_number IS NULL)
UNION ALL SELECT 'airports without coordinates (kept)', (SELECT SUM(dq_missing_coords) FROM cln_airports)
UNION ALL SELECT 'total flight rows removed', (SELECT COUNT(*) FROM stg_flights) - (SELECT COUNT(*) FROM cln_flights);

-- COMMAND ----------

CREATE OR REPLACE TABLE dq_assertions AS
WITH c AS (
  SELECT 'every clean flight is in fact_flights' AS check_name, (SELECT COUNT(*) FROM cln_flights) - (SELECT COUNT(*) FROM fact_flights) AS failed_rows
  UNION ALL SELECT 'flight key unique in fact', (SELECT COUNT(*) FROM (SELECT date_key, airline_code, flight_number, origin_code, dest_code, sched_dep_hhmm, COUNT(*) AS n
      FROM fact_flights WHERE origin_code <> 'UNK' GROUP BY date_key, airline_code, flight_number, origin_code, dest_code, sched_dep_hhmm HAVING COUNT(*) > 1) x)
  UNION ALL SELECT 'airline exists in dim_airline', (SELECT COUNT(*) FROM fact_flights f LEFT JOIN dim_airline a ON a.airline_code = f.airline_code WHERE a.airline_code IS NULL)
  UNION ALL SELECT 'origin exists in dim_airport', (SELECT COUNT(*) FROM fact_flights f LEFT JOIN dim_airport a ON a.airport_code = f.origin_code WHERE a.airport_code IS NULL)
  UNION ALL SELECT 'destination exists in dim_airport', (SELECT COUNT(*) FROM fact_flights f LEFT JOIN dim_airport a ON a.airport_code = f.dest_code WHERE a.airport_code IS NULL)
  UNION ALL SELECT 'date exists in dim_date', (SELECT COUNT(*) FROM fact_flights f LEFT JOIN dim_date d ON d.date_key = f.date_key WHERE d.date_key IS NULL)
  UNION ALL SELECT 'cancellation code exists in dim_cancellation', (SELECT COUNT(*) FROM fact_flights f LEFT JOIN dim_cancellation c ON c.cancellation_code = f.cancellation_code WHERE c.cancellation_code IS NULL)
  UNION ALL SELECT 'every cancelled flight has a reason', (SELECT COUNT(*) FROM fact_flights WHERE is_cancelled = 1 AND cancellation_code = 'N')
  UNION ALL SELECT 'status flags exclusive (cancelled + diverted <= 1)', (SELECT COUNT(*) FROM fact_flights WHERE is_cancelled + is_diverted > 1)
  UNION ALL SELECT 'on-time + late = completed flights', (SELECT ABS(SUM(is_on_time + is_arr_delayed_15) - SUM(1 - is_cancelled - is_diverted)) FROM fact_flights)
  UNION ALL SELECT 'monthly flights sum = fact rows', (SELECT ABS((SELECT SUM(flights) FROM a_monthly) - (SELECT COUNT(*) FROM fact_flights)))
  UNION ALL SELECT 'airline flights sum = fact rows', (SELECT ABS((SELECT SUM(flights) FROM a_airline) - (SELECT COUNT(*) FROM fact_flights)))
  UNION ALL SELECT 'positive distance', (SELECT COUNT(*) FROM fact_flights WHERE distance_mi <= 0)
  UNION ALL SELECT 'airport codes unique in dim_airport', (SELECT COUNT(*) - COUNT(DISTINCT airport_code) FROM dim_airport)
)
SELECT check_name, failed_rows, CASE WHEN failed_rows = 0 THEN 'PASS' ELSE 'FAIL' END AS status FROM c;

-- COMMAND ----------

SELECT * FROM dq_row_counts ORDER BY entity;

-- COMMAND ----------

SELECT * FROM dq_assertions ORDER BY status, check_name;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## Visual queries (same as the Lakeview dashboard)

-- COMMAND ----------

SELECT * FROM a_kpi_headline;

-- COMMAND ----------

-- Visualization: On-time arrival % by month (line: x=month_label, y=on_time_pct)
SELECT month_label, on_time_pct FROM a_monthly ORDER BY month;

-- COMMAND ----------

-- Visualization: Cancellation rate by month (%) (bar: x=month_label, y=cancelled_pct)
SELECT month_label, cancelled_pct FROM a_monthly ORDER BY month;

-- COMMAND ----------

-- Visualization: On-time arrival % by airline (hbar: x=airline_name, y=on_time_pct)
SELECT airline_name, on_time_pct FROM a_airline ORDER BY on_time_pct DESC;

-- COMMAND ----------

-- Visualization: Share of late-arrival minutes by cause (hbar: x=cause, y=share_pct)
SELECT cause, share_pct FROM a_delay_causes ORDER BY share_pct DESC;

-- COMMAND ----------

-- Visualization: Avg departure delay by scheduled hour (min) (bar: x=sched_dep_hour, y=avg_dep_delay_min)
SELECT sched_dep_hour, avg_dep_delay_min FROM a_hourly ORDER BY sched_dep_hour;

-- COMMAND ----------

-- Visualization: Avg departure delay, 10 busiest origins (min) (hbar: x=origin_code, y=avg_dep_delay_min)
SELECT origin_code, avg_dep_delay_min FROM (SELECT origin_code, avg_dep_delay_min, departures FROM a_origin_airports ORDER BY departures DESC LIMIT 10) t ORDER BY avg_dep_delay_min DESC;
